public static void addOrRemoveSelection(UserId	_user, TFMDocumentDeviceId _device, str _ref, str _context)
{
    TFMMultiselectionTable table;

    ttsbegin;
    table = TFMMultiselectionTable::Find(_user, _ref,_device,true);

    table.UserId			= _user;
    table.Reference			= _ref;
    table.DeviceId			= _device;
    table.ClassName			= _context;
    if (table.RecId)
    {
        table.delete();
    }
    else
    {
        table.insert();
    }
    ttscommit;
}

public static TFMMultiselectionTable Find(UserId	_user, str _ref, TFMDocumentDeviceId _device, boolean _select4Update = false)
{
    TFMMultiselectionTable table;
    table.selectForUpdate(_select4Update);

    select firstonly table where table.UserId == _user && table.Reference == _ref;

    return table;

}

public static TFMMultiselectionTable RemoveAllInContext(UserId	_user, str _context, TFMDocumentDeviceId _device)
{
    TFMMultiselectionTable table;

    ttsbegin;
    delete_from table where table.UserId == _user && table.DeviceId == _device && table.ClassName == _context;
    ttscommit;
    return table;
}

public static TFMMultiselectionTable RemoveAllForUserOnDevice(UserId _user, TFMDocumentDeviceId _device)
{
    TFMMultiselectionTable table;

    ttsbegin;
    delete_from table where table.UserId == _user && table.DeviceId == _device;
    ttscommit;
    return table;
}

public static Set GetAllInContext(UserId	_user, str _context, TFMDocumentDeviceId _device)
{
    TFMMultiselectionTable	table;
    Set						allRefs = new Set(Types::String);

    while select Reference from table where table.UserId == _user && table.DeviceId == _device && table.ClassName == _context
    {
        allRefs.add(table.Reference);
    }

    return allRefs;
}
